// Model — SQL Server rowversion, managed by the database
public class Order
{
    public int Id { get; set; }
    public decimal Total { get; set; }
    public byte[] RowVersion { get; set; } = null!;
}

protected override void OnModelCreating(ModelBuilder b)
{
    b.Entity<Order>().Property(o => o.RowVersion).IsRowVersion();
}

// Save with conflict handling
public async Task<UpdateResult> UpdateTotalAsync(int id, decimal newTotal)
{
    var order = await _db.Orders.FindAsync(id);   // RowVersion captured as original
    order.Total = newTotal;

    try
    {
        await _db.SaveChangesAsync();
        return UpdateResult.Ok;
    }
    catch (DbUpdateConcurrencyException ex)
    {
        var entry = ex.Entries.Single();
        var databaseValues = await entry.GetDatabaseValuesAsync();

        if (databaseValues is null)               // row deleted underneath us
            return UpdateResult.DeletedBySomeoneElse;

        // Option A: show the user the competing version and abort
        var theirs = (byte[])databaseValues["RowVersion"]!;
        return UpdateResult.Conflict(currentVersion: theirs);

        // Option B: last-write-wins
        // entry.OriginalValues.SetValues(databaseValues);
        // await _db.SaveChangesAsync();
    }
}

